function author(id){if(id==='me')return '익명 · 나';const post=state.posts.find(x=>x.id===context.id||x.id===context.post);if(post){if(id===post.author)return '익명 · 글쓴이';const participants=[...new Set(post.comments.map(x=>x.author).filter(x=>x!==post.author&&x!=='me'))];return '익명 '+(participants.indexOf(id)+1||1);}return '익명';}

function history(items){return items.length?items.map(x=>`<div class="fx-row"><span>${esc(x.title)}<br><small>${new Date(x.at).toLocaleString('ko-KR')}</small></span><b>${x.delta>0?'+':''}${x.delta}</b></div>`).join(''):'<p>아직 내역이 없어요.</p>';}

