function postSketch(post){const gender=anonymousGender(post.author);const variants=gender==='여성'?[0,2,4,6,8,10]:gender==='남성'?[1,3,5,7,9,11]:[];if(!variants.length)return '<svg viewBox="0 0 72 80" aria-hidden="true"><circle cx="36" cy="27" r="12" fill="none" stroke="currentColor"/><path d="M14 70Q14 46 36 46Q58 46 58 70" fill="none" stroke="currentColor"/></svg>';if(!variants.includes(anonAssignments[post.id])){const used=new Set(Object.values(anonAssignments));let pool=variants.filter(i=>!used.has(i));if(!pool.length)pool=variants;anonAssignments[post.id]=pool[Math.floor(Math.random()*pool.length)];}return anonSketch(anonAssignments[post.id]);}
