function communityView(){let posts=state.posts.filter(p=>p.author==='me'||!state.blocks.includes(p.author));const topic=p=>p.topic||(p.id==='p2'?'취향':'일상');posts.sort((a,b)=>tab==='인기 글'?b.likes.length-a.likes.length||b.at-a.at:b.at-a.at);const exchangeCount=state.requests.filter(r=>r.direction==='in'&&r.status==='received'&&!state.blocks.includes(r.person)).length;const unread=state.notifications.filter(n=>!n.read).length+exchangeCount;return `<div class="comm-heading"><div><h1 class="category-title">익명 이야기<svg class="category-sketch" viewBox="0 0 48 48" aria-hidden="true"><path d="M8 10Q20 7 32 11L32 27Q23 30 15 27L8 33L10 25Q6 19 8 10Z M17 16L26 16 M16 21L24 21 M36 17Q42 18 41 31L43 38L34 34L27 34"/></svg></h1><p class="category-subtitle">마음 편히, 이름 없이 나누는 이야기</p></div><button data-fx="notifications" class="comm-bell" aria-label="커뮤니티 알림 ${unread}개"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 10c0-8 12-8 12 0v5l2 3H4l2-3ZM9 21h6"/></svg>${unread?'<i></i>':''}</button></div><div class="comm-tools"><button class="comm-tool comm-exchange" data-fx="exchange">프로필 교환${exchangeCount?`<span class="exchange-count">${exchangeCount}</span>`:''}</button>${button('내 이야기','activity','comm-tool')}${button('글쓰기','compose-post','comm-write')}${button('이용수칙','community-guide','comm-tool')}</div>${exchangeCount?`<button class="exchange-arrival" data-fx="exchange"><span>내 이야기에 마음이 닿았어요<small>프로필 교환 요청 ${exchangeCount}개</small></span><b aria-hidden="true">›</b></button>`:''}<button class="comm-question" data-fx="compose-prompt"><span>오늘의 질문</span> 오늘, 마음에 남은 장면은? <b aria-hidden="true">›</b></button><p class="comm-privacy">서로 수락하기 전까지 프로필은 공개되지 않아요.</p><div class="comm-feed-heading"><h2>우리의 일상 조각</h2></div><div class="comm-sort">${['새 글','인기 글'].map(t=>`<button data-fx="community-sort:${t}" aria-pressed="${tab===t}">${t}</button>`).join('')}</div><div class="comm-feed">`+(posts.length?posts.map(p=>`<article class="comm-entry"><button class="comm-post-link" data-fx="post:${p.id}"><span class="comm-entry-meta"><span class="comm-anon">${postSketch(p)}<span>${anonymousBadge(p.author)} ${p.author==='me'?'나':''}</span></span><span>${postAge(p.at)}</span></span><p>${esc(p.body.slice(0,160))}${p.body.length>160?'…':''}</p>${p.photos?.length?`<span class="comm-photo-preview">${p.photos.slice(0,3).map(src=>`<img src="${esc(src)}" alt="익명글 첨부 사진" loading="lazy">`).join('')}</span>`:''}<span class="comm-entry-footer"><span>공감 ${p.likes.length}</span><span>이야기 ${p.comments.filter(x=>x.author==='me'||!state.blocks.includes(x.author)).length}</span>${p.photos?.length?'<span>사진 '+p.photos.length+'</span>':''}${p.audio?'<span>음성</span>':''}</span></button></article>`).join(''):'<div class="comm-empty">아직 이 주제의 이야기가 없어요.<br>첫 장면을 남겨볼까요?'+button('익명으로 글쓰기','compose-post','comm-write')+'</div>')+'</div><p class="comm-end">a little closer, naturally.</p>';}
