const dateLabel=at=>new Date(at).toLocaleDateString('ko-KR');
function couponStatus(x){return x.used?'사용 완료':now()>=x.at+7*R.DAY?'기간 만료':'사용 가능';}
function distanceLabel(i){if(!userLocation)return '';const rad=x=>x*Math.PI/180,[a,b]=userLocation,[c,d]=shopPoints[i],q=Math.sin(rad(c-a)/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(rad(d-b)/2)**2,metres=6371000*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q));return metres<1000?Math.round(metres/10)*10+'m':(metres/1000).toFixed(1)+'km';}
function placesView(){return `<div class="fx-page-heading"><div><h1>가까운 곳, 야화 혜택</h1><p class="place-benefit-caption">마음에 드는 매장에서 쿠폰을 받아보세요.</p></div><button class="fx-help" data-fx="place-help" aria-label="플레이스 이용 안내">?</button></div><div class="place-wallet" aria-label="나의 혜택"><button data-fx="coupons"><span>내 쿠폰함</span><strong>${state.coupons.filter(x=>couponStatus(x)==='사용 가능').length}<small>장</small><i>›</i></strong></button><button data-fx="point-ledger"><span>매장 포인트</span><strong>${state.points.toLocaleString()}<small>P</small><i>›</i></strong></button></div><div class="fx-place-search"><label class="sr-only" for="fx-map-query">지역 또는 매장 검색</label><input id="fx-map-query" type="search" placeholder="지역이나 매장을 찾아보세요"><button data-fx="map-search" aria-label="검색">검색</button></div><div id="fx-map-results" aria-live="polite"></div><div class="fx-tabs" id="fx-place-tabs">${['전체','혼술바','카페','밥집','디저트'].map(t=>`<button data-fx="place-filter:${t}" aria-pressed="${placeTab===t}">${t}</button>`).join('')}</div><div class="fx-map-wrap"><div class="fx-map" id="fx-live-map" aria-label="매장 위치 지도"></div><div class="fx-map-status" id="fx-map-status" role="status">지도를 불러오는 중이에요.</div><button class="fx-location" data-fx="map-locate" aria-label="내 위치로 이동">내 위치</button></div><section class="fx-place-sheet ${placeExpanded?'expanded':''}" id="fx-place-sheet"><button class="fx-sheet-toggle" data-fx="place-expand" aria-expanded="${placeExpanded}"><span aria-hidden="true"></span><b id="fx-area-label">지도 안의 혜택</b><small>${placeExpanded?'접기':'전체 보기'}</small></button><div id="fx-place-list"></div></section><button class="place-point-help" data-fx="point-help">포인트 적립·사용 안내 <span aria-hidden="true">›</span></button><small>성수 주변 4개 매장 · 혜택은 시연용 예시예요.</small>`;}
function shopCard(i){const s=stores[i],coupon=state.coupons.find(x=>x.store===i);return `<article class="fx-shop-card ${selectedShop===i?'selected':''}"><div class="fx-shop-meta"><span>${s[1]}</span><span>${distanceLabel(i)}</span></div><button class="fx-shop-title" data-fx="shop:${i}"><span>${s[0]}</span><span aria-hidden="true">›</span></button><p class="fx-shop-benefit">${s[2]}</p><small>${s[4]} · 예시 영업시간</small><div class="fx-actions">${button(coupon?'내 쿠폰 보기':'쿠폰 받기',coupon?'coupon-detail:'+i:'coupon-get:'+i,'fx-small')}${button('매장 자세히','shop:'+i,'fx-small')}</div></article>`;}
function updatePlaceResults(){if(active!=='features'||view!=='places')return;const host=$('fx-place-list');if(!host)return;const toggle=body.querySelector('[data-fx="place-expand"]');if(toggle){toggle.setAttribute('aria-expanded',placeExpanded);toggle.querySelector('small').textContent=placeExpanded?'접기':'전체 보기';}$('fx-place-sheet').classList.toggle('expanded',placeExpanded);const bounds=map?.getBounds();let ids=stores.map((s,i)=>i).filter(i=>(placeTab==='전체'||stores[i][1]===placeTab)&&(!bounds||bounds.contains(shopPoints[i])));if(selectedShop!==null)ids.sort((a,b)=>(b===selectedShop)-(a===selectedShop));host.innerHTML=ids.length?ids.map(shopCard).join(''):`<div class="fx-empty"><p>이 지도 범위에는 아직 혜택이 없어요.</p><div class="fx-actions">${button('지도 넓게 보기','map-widen','fx-small')}${button('성수 혜택 보기','map-reset','fx-small')}</div></div>`;$('fx-area-label').textContent='지도 안의 혜택 · '+ids.length;document.querySelectorAll('#fx-place-tabs button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.fx==='place-filter:'+placeTab));mapMarkers.forEach(({marker,i})=>{const visible=placeTab==='전체'||stores[i][1]===placeTab;if(visible&&!map.hasLayer(marker))marker.addTo(map);else if(!visible&&map.hasLayer(marker))map.removeLayer(marker);});}
function disposeMap(){mapGeneration++;searchAbort?.abort();searchAbort=null;clearTimeout(mapTimer);mapObserver?.disconnect();mapObserver=null;if(map){const c=map.getCenter();mapCenter=[c.lat,c.lng];mapZoom=map.getZoom();map.remove();map=null;}mapMarkers=[];mapLayer=null;}
function mapStatus(text,retry=false){const el=$('fx-map-status');if(el){el.hidden=!text;el.innerHTML=esc(text)+(retry?button('다시 연결','map-retry','fx-small'):'');}}
function initMap(){disposeMap();const generation=mapGeneration,host=$('fx-live-map');if(!host)return;if(!window.L){mapStatus('지도 연결이 어려워요. 아래 매장 목록은 이용할 수 있어요.',true);updatePlaceResults();return;}try{map=L.map(host,{zoomControl:false}).setView(mapCenter,mapZoom);L.control.zoom({position:'topright'}).addTo(map);mapLayer=L.tileLayer('https://{s}.tile.openstreetmap.fr/hot/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap · HOT · OSM France'});mapLayer.on('load',()=>{if(generation!==mapGeneration)return;clearTimeout(mapTimer);mapStatus('');});mapLayer.on('tileerror',()=>{if(generation===mapGeneration)mapStatus('지도 일부를 불러오지 못했어요.',true);});mapLayer.addTo(map);mapTimer=setTimeout(()=>{if(generation===mapGeneration)mapStatus('연결이 느려요. 매장 목록에서 먼저 확인해보세요.',true);},12000);mapMarkers=stores.map((s,i)=>{const marker=L.marker(shopPoints[i],{title:s[0],alt:s[0]}).on('click',()=>{selectedShop=i;placeExpanded=false;$('fx-place-sheet').classList.remove('expanded');map.panTo(shopPoints[i]);updatePlaceResults();$('fx-place-list')?.querySelector('.selected')?.scrollIntoView?.({block:'nearest',behavior:'smooth'});});if(placeTab==='전체'||s[1]===placeTab)marker.addTo(map);return {marker,i};});map.on('moveend',updatePlaceResults);if(userLocation)L.circleMarker(userLocation,{radius:6,color:'#6887A0',fillOpacity:.9}).addTo(map);if(window.ResizeObserver){mapObserver=new ResizeObserver(()=>{if(generation===mapGeneration)map?.invalidateSize();});mapObserver.observe(host);}requestAnimationFrame(()=>{if(generation===mapGeneration){map?.invalidateSize();updatePlaceResults();}});updatePlaceResults();}catch{disposeMap();mapStatus('지도를 열지 못했어요. 매장 목록에서 확인해주세요.',true);updatePlaceResults();}}
async function searchPlaces(){const q=$('fx-map-query')?.value.trim();if(!q)return;searchAbort?.abort();searchAbort=new AbortController();const controller=searchAbort,generation=mapGeneration,results=$('fx-map-results'),local=stores.map((s,i)=>({s,i})).filter(x=>(x.s[0]+' '+x.s[3]).includes(q));results.innerHTML=local.map(x=>row(x.s[0],'map-select:'+x.i)).join('')+'<small>지역을 찾고 있어요…</small>';try{const response=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&countrycodes=kr&limit=4&q='+encodeURIComponent(q),{signal:controller.signal});if(!response.ok)throw Error();const data=await response.json();if(controller.signal.aborted||generation!==mapGeneration||view!=='places')return;results.innerHTML=local.map(x=>row(x.s[0],'map-select:'+x.i)).join('');for(const p of data){const lat=Number(p.lat),lon=Number(p.lon);if(!Number.isFinite(lat)||!Number.isFinite(lon))continue;const b=document.createElement('button');b.className='fx-row';b.textContent=p.display_name;b.onclick=()=>{placeTab='전체';selectedShop=null;map?.setView([lat,lon],15);results.replaceChildren();updatePlaceResults();};results.append(b);}if(!results.children.length)results.innerHTML='<p class="fx-note">검색 결과가 없어요. 다른 지역명으로 찾아보세요.</p>';}catch(e){if(e.name==='AbortError'||generation!==mapGeneration)return;results.innerHTML=local.map(x=>row(x.s[0],'map-select:'+x.i)).join('')+'<p class="fx-note">지역 검색 연결이 어려워요. 매장 이름으로 다시 검색하거나 지도를 움직여주세요.</p>';}}
function shopView(id){const s=stores[id];if(!s)return title('매장을 찾을 수 없어요.');const coupon=state.coupons.find(x=>x.store===id);return `<small>${s[1]} ${distanceLabel(id)}</small>`+title(s[0])+`<div class="fx-benefit"><small>YAHWA PLACE BENEFIT</small><h2>${s[2]}</h2><p>${eligible[id]}</p></div><dl class="fx-shop-details"><div><dt>주소</dt><dd>${s[3]}</dd></div><div><dt>영업시간</dt><dd>${s[4]} · 시연 정보</dd></div><div><dt>사용 조건</dt><dd>${s[5]}</dd></div><div><dt>중복 할인</dt><dd>${combinations[id]}</dd></div><div><dt>유효기간</dt><dd>발급 시점부터 7일 · 1회 사용</dd></div></dl>`+button(coupon?'내 쿠폰 확인하기':'혜택 쿠폰 받기',coupon?'coupon-detail:'+id:'coupon-get:'+id)+`<div class="fx-actions">${button('지도에서 보기','shop-map:'+id,'fx-small')}${button('주소 복사','shop-address:'+id,'fx-small')}</div>`+(id===0?'<a class="fx-row" href="https://www.google.com/maps/dir/?api=1&travelmode=walking&destination='+encodeURIComponent(s[3])+'" target="_blank" rel="noopener">도보 길찾기 ↗</a>':'')+'<small>매장·영업시간·혜택은 시연 예시이며 실제 사용은 불가해요.</small>';}
function couponsView(){const items=state.coupons.filter(x=>couponStatus(x)===couponTab);return title('나의 쿠폰함','함께 머물 순간에 작은 혜택을 더해요.')+`<div class="fx-tabs">${['사용 가능','사용 완료','기간 만료'].map(t=>`<button data-fx="coupon-tab:${t}" aria-pressed="${couponTab===t}">${t} ${state.coupons.filter(x=>couponStatus(x)===t).length}</button>`).join('')}</div>`+(items.length?items.map(x=>`<article class="fx-coupon"><small>${stores[x.store][1]} · ${couponStatus(x)}</small><h2>${stores[x.store][2]}</h2><p>${stores[x.store][0]}</p><small>${x.used?'사용일 '+dateLabel(x.usedAt||x.at):dateLabel(x.at+7*R.DAY)+'까지'}</small>${button('쿠폰 자세히','coupon-detail:'+x.store,'fx-small')}</article>`).join(''):`<div class="fx-empty"><p>${couponTab==='사용 가능'?'아직 받은 혜택이 없어요.':couponTab+' 쿠폰이 없어요.'}</p><small>플레이스에서 마음에 드는 공간을 찾아보세요.</small></div>`)+button('주변 혜택 보기','places');}
function couponView(id,confirm){const x=state.coupons.find(x=>x.store===id),s=stores[id];if(!x||!s)return title('쿠폰을 먼저 받아주세요.')+button('플레이스 보기','places');const status=couponStatus(x),available=status==='사용 가능';return title(confirm?'직원에게 보여주세요':'함께 머물 작은 혜택')+`<article class="fx-coupon"><small>${status} · 시연 쿠폰</small><h2>${s[2]}</h2><p>${s[0]}</p><dl class="fx-shop-details"><div><dt>대상</dt><dd>${eligible[id]}</dd></div><div><dt>조건</dt><dd>${s[5]}</dd></div><div><dt>중복 사용</dt><dd>${combinations[id]}</dd></div><div><dt>사용 기한</dt><dd>${new Date(x.at+7*R.DAY).toLocaleString('ko-KR')}</dd></div></dl></article>`+(available?(confirm?'<p class="fx-note">직원이 확인한 뒤에만 사용 완료를 눌러주세요. 완료 후에는 다시 사용할 수 없어요.</p>'+button('시연 사용 완료','coupon-use:'+id)+button('아직 사용하지 않을게요','coupon-detail:'+id,'fx-small'):button('매장에서 사용하기','coupon-confirm:'+id)):'<p class="fx-note">'+(x.used?'이미 사용한 쿠폰이에요.':'사용 기한이 지나 다시 사용할 수 없어요.')+'</p>')+row('매장 정보 보기','shop:'+id)+'<small>실제 매장 할인이 제공되지 않는 UI 시연 쿠폰이에요.</small>';}
function credentialBadges(){return state.credentials.filter(x=>x.status==='시연 승인').map(x=>`<button class="fx-cert-badge ${x.kind==='전화번호'?'phone-cert':''}" data-fx="credentials">✓ ${x.kind==='전화번호'?'전화번호 인증':esc(x.value)}${x.kind==='학력'?' '+esc(x.schoolState||''):''}</button>`).join('');}
function credentialsView(){return title('배지 · 인증 관리','작은 확인으로, 조금 더 편안한 만남.')+`<div class="cert-overview"><span class="cert-shield">✓</span><div><strong>${state.credentials.filter(x=>x.status==='시연 승인').length}개의 인증 배지</strong><p>승인된 정보만 프로필에 표시돼요.</p></div></div><div class="cert-steps"><span>1 정보 입력</span><span>2 확인 요청</span><span>3 승인 · 배지</span></div><p class="cert-section-label">나의 인증 내역</p>${state.credentials.length?'':'<p class="cert-empty">아직 인증한 정보가 없어요.<br>아래에서 확인할 정보를 선택해 주세요.</p>'}`+`<div class="fx-cert-records">${state.credentials.map(x=>`<div class="fx-card"><small>${x.kind} ${x.year?'· '+x.year+'년 기준':''}</small><p>${esc(x.value)} ${esc(x.schoolState||'')}</p><b>${x.status}</b>${x.status==='다시 확인 필요'?'<p>'+esc(x.reason||'제출 정보를 다시 확인해주세요.')+'</p>':''}</div>`).join('')}</div>`+'<p class="cert-section-label">새 인증 신청</p>'+select('인증 종류','fx-cert-kind',['학력','직장','소득','전화번호'])+`<div id="fx-cert-school">${select('학적 상태','fx-cert-school-state',['선택해주세요','졸업','재학 중','중퇴'])}</div><div id="fx-cert-common">${field('학교·회사명','fx-cert-value')}${field('소속 이메일 · 시연용','fx-cert-email','','email')}${button('인증코드 받기 · 재발급','cert-code','fx-small')}${field('인증코드','fx-cert-code')}<small id="fx-cert-countdown" role="status">시연 코드 123456 · 유효시간 3분</small></div><div id="fx-cert-income" hidden>${select('소득 구간','fx-cert-income-value',['선택해주세요','연 소득 7천만+','연 소득 1억+','연 소득 2억+'])}${field('소득 기준연도','fx-cert-year',new Date(now()).getFullYear()-1,'number')}<label>소득 증빙<input type="file" id="fx-cert-proof" accept="image/*,.pdf"></label><small>자료는 전송하지 않고 파일명만 확인해요.</small></div>`+button('시연 확인 요청','cert-submit')+'<small>실제 이메일·인증은 연결되지 않았어요. 요청 후 아래 시연 도구에서 승인·보완 상태를 확인할 수 있어요.</small>';}
function syncCertForm(){const kind=$('fx-cert-kind')?.value;if(!kind)return;$('fx-cert-school').hidden=kind!=='학력';$('fx-cert-common').hidden=kind==='소득';$('fx-cert-income').hidden=kind!=='소득';$('fx-cert-email').closest('label')?.toggleAttribute('hidden',kind==='전화번호');$('fx-cert-value').placeholder=kind==='전화번호'?'01012345678':'학교·회사명';updateCertCountdown();}
function updateCertCountdown(){const el=$('fx-cert-countdown');if(!el)return;const sec=certSession?Math.max(0,Math.ceil((certSession.at+180000-now())/1000)):0;el.textContent=certSession?(sec?'시연 코드 123456 · '+Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0')+' 남음':'시간이 지났어요. 코드를 다시 받아주세요.'):'이름과 이메일을 입력하고 코드를 받아주세요.';}
function settingsView(){const permission=typeof Notification==='undefined'?'지원되지 않음':({granted:'허용',denied:'차단',default:'미설정'})[Notification.permission],items=[['introductions','새로운 소개','새로운 인연이 도착했을 때'],['likes','받은 호감','누군가 호감을 보냈을 때'],['letters','받은 편지','새 편지가 도착했을 때'],['replies','편지 답장','상대가 답장을 보냈을 때'],['comments','내 글의 댓글','내가 쓴 글에 댓글이 달렸을 때'],['commentReplies','내 댓글의 답글','내 댓글에 답글이 달렸을 때'],['exchange','프로필 교환','교환 신청과 수락 소식'],['coupons','쿠폰 만료','보유 쿠폰의 만료일이 다가올 때']];return title('알림 설정')+'<label class="fx-row notification-master"><span>전체 알림<small>모든 알림을 한 번에 켜거나 꺼요.</small></span><input aria-label="전체 알림" class="fx-switch" type="checkbox" data-setting="app" '+(state.settings.app?'checked':'')+'></label><div class="notification-options">'+items.map(([key,label,desc])=>'<label class="fx-row"><span>'+label+'<small>'+desc+'</small></span><input aria-label="'+label+'" class="fx-switch" type="checkbox" data-setting="'+key+'" '+(state.settings[key]?'checked':'')+' '+(!state.settings.app?'disabled':'')+'></label>').join('')+'</div><p class="quiet">기기 알림 권한 · '+permission+'</p>'+button('기기 권한 확인','notification-permission','fx-small')+'<small>시연 설정은 이 브라우저에 저장돼요. 실제 푸시는 발송하지 않아요.</small>';}
function exchangeView(){state.requests.filter(x=>x.direction==='in').forEach(x=>x.seen=true);persist();const labels={received:'받은 요청',sent:'보낸 요청',done:'교환 완료',released:'교환 해제',declined:'거절'},items=state.requests.filter(r=>!state.blocks.includes(r.person)&&(exchangeTab==='받은 요청'?r.direction==='in'&&r.status==='received':exchangeTab==='보낸 요청'?r.direction==='out'&&r.status==='sent':['done','released','declined'].includes(r.status)));return title('이야기에서 시작한 인연','요청 10리프 · 수락 무료 · 연락처는 공개되지 않아요.')+`<div class="fx-tabs">${['받은 요청','보낸 요청','교환 기록'].map(t=>`<button data-fx="exchange-tab:${t}" aria-pressed="${exchangeTab===t}">${t}</button>`).join('')}</div>`+(items.length?items.map(r=>`<article class="fx-card"><small>${labels[r.status]}</small><h2>${r.status==='done'?esc(demoMatches[r.person].name):author(r.person)}</h2><p>${esc(r.context||'이야기를 통해 알아가요.')}</p>${r.post?row('함께 이야기한 게시글','post:'+r.post):''}<div class="fx-actions">${r.status==='received'?button('수락','exchange-accept:'+r.id,'fx-small')+button('거절','exchange-decline:'+r.id,'fx-small'):r.status==='done'?button('프로필 보기','person:'+r.person,'fx-small')+button('교환 해제','exchange-release:'+r.id,'fx-small'):''}</div></article>`).join(''):'<p class="fx-empty">아직 '+exchangeTab+'이 없어요.</p>');}
const communityRules=[['익명은 함께 지켜요','얼굴 사진, 프로필 캡처, 신상을 알아볼 수 있는 내용은 올리지 말아주세요.'],['연락처는 편지로','전화번호·SNS·오픈채팅 링크는 공개하지 않아요. 프로필 교환 후 편지로 이야기를 이어가세요.'],['광고와 거래는 삼가요','홍보·판매·구인 글은 올릴 수 없어요. 매장 혜택은 플레이스에서 확인해주세요.'],['금전 요구는 금지해요','송금·대출·투자 권유 등 피해를 유발하는 내용은 올릴 수 없어요.'],['서로를 존중해요','욕설·비방·혐오·차별·성희롱 표현을 삼가주세요.'],['성적 노출은 올릴 수 없어요','성적 사진·음성·묘사와 성매매 유도는 금지해요.'],['위험한 이미지는 피해요','유혈·잔혹한 장면이나 폭력·자해를 부추기는 내용은 올리지 말아주세요.'],['내가 만든 이야기로 참여해요','타인의 사진·음성 도용, 사칭, 반복 게시를 삼가주세요.'],['문제가 보이면 신고해주세요','글·댓글의 신고 메뉴에서 알려주세요. 직접 다투기보다 신고로 도움을 요청해주세요.']];
async function auditAction(a,v,n,c){
if(a==='community-topic'){communityTopic=v;render();return true;}
if(a==='compose-prompt'){navTo('compose-post');$('fx-post-body').placeholder='오늘 마음에 남은 장면을 편하게 적어주세요.';$('fx-post-body').focus();return true;}
if(a==='my-preview'){show('preview');return true;}
if(a==='notice-open'){const notice=state.notifications[n];if(notice){notice.read=true;persist();if(notice.post)navTo('post',{id:notice.post});else if(notice.letter)openLetter(notice.letter);else navTo('exchange');}return true;}
if(a==='gray-toggle'){state.gray=!state.gray;persist();show('mypage');return true;}
if(a==='map-search'){await searchPlaces();return true;}
if(a==='map-locate'){if(!navigator.geolocation){toast('현재 위치를 지원하지 않아요. 지역 검색을 이용해주세요.');return true;}const generation=mapGeneration;toast('현재 위치를 확인하고 있어요.');navigator.geolocation.getCurrentPosition(p=>{if(generation!==mapGeneration||view!=='places')return;userLocation=[p.coords.latitude,p.coords.longitude];map?.setView(userLocation,15);if(map)L.circleMarker(userLocation,{radius:6,color:'#6887A0'}).addTo(map);updatePlaceResults();},()=>{if(generation===mapGeneration)toast('위치 권한을 확인해주세요. 지역 검색으로도 찾을 수 있어요.');},{timeout:10000,maximumAge:60000});return true;}
if(a==='map-retry'){initMap();return true;}
if(a==='map-reset'||a==='map-select'||a==='map-widen'){if(a==='map-widen')map?.zoomOut();else{placeTab='전체';selectedShop=a==='map-select'?n:null;map?.setView(a==='map-select'?shopPoints[n]:shopPoints[0],15);$('fx-map-results')?.replaceChildren();}updatePlaceResults();return true;}
if(a==='place-expand'){placeExpanded=!placeExpanded;$('fx-place-sheet').classList.toggle('expanded',placeExpanded);const b=body.querySelector('[data-fx="place-expand"]');b.setAttribute('aria-expanded',placeExpanded);b.querySelector('small').textContent=placeExpanded?'접기':'전체 보기';return true;}
if(a==='shop-map'){mapCenter=shopPoints[n];mapZoom=16;selectedShop=n;placeTab='전체';navTo('places');return true;}
if(a==='shop-address'){try{await navigator.clipboard.writeText(stores[n][3]);toast('주소를 복사했어요.');}catch{toast('주소를 길게 눌러 복사해주세요.');}return true;}
if(a==='coupon-detail'){navTo('coupon-detail',{id:n});return true;}
if(a==='coupon-tab'){couponTab=v;render();return true;}
if(a==='exchange-tab'){exchangeTab=v;render();return true;}
if(a==='exchange-release-do'){const r=state.requests.find(x=>x.id===v);if(r?.status==='done')r.status='released';exchangeTab='교환 기록';persist();navTo('exchange');return true;}
if(a==='unhide-one'){state.hidden=state.hidden.filter(i=>i!==n);persist();render();return true;}
if(a==='notification-permission'){if(typeof Notification!=='undefined'&&Notification.permission==='default'){try{await Notification.requestPermission();if(view==='settings')render();}catch{navTo('permission-help');}}else navTo('permission-help');return true;}
if(a==='withdraw-do'){localStorage.removeItem(KEY);location.hash='welcome';location.reload();return true;}
if(a==='cert-code'){const value=$('fx-cert-value').value.trim(),email=$('fx-cert-email').value.trim(),kind=$('fx-cert-kind').value;if(kind==='전화번호'?!/^01[016789][0-9]{7,8}$/.test(value.replace(/-/g,'')):(!value||!/^\S+@\S+\.\S+$/.test(email))){toast(kind==='전화번호'?'휴대전화 번호를 확인해주세요.':'소속명과 이메일 형식을 확인해주세요.');return true;}certSession={at:now(),value,email,kind};$('fx-cert-code').value='';updateCertCountdown();toast('시연 코드 123456 · 3분 이내 입력');return true;}
if(a==='cert-submit'){const kind=$('fx-cert-kind').value,schoolState=$('fx-cert-school').querySelector('select').value,value=kind==='소득'?$('fx-cert-income-value').value:$('fx-cert-value').value.trim(),year=Number($('fx-cert-year').value);if(kind==='학력'&&schoolState==='선택해주세요'){toast('학적 상태를 선택해주세요.');return true;}if(kind==='소득'){if(value==='선택해주세요'||!$('fx-cert-proof').files.length||year<2000||year>=new Date(now()).getFullYear()){toast('소득 구간·자료·지난 기준연도를 확인해주세요.');return true;}}else if(!certSession||certSession.value!==value||certSession.kind!==kind||certSession.email!==$('fx-cert-email').value.trim()||now()-certSession.at>=180000||$('fx-cert-code').value!=='123456'){toast('정보와 유효한 시연 인증코드를 확인해주세요.');return true;}state.credentials=state.credentials.filter(x=>x.kind!==kind);state.credentials.push({kind,value,schoolState:kind==='학력'?schoolState:'',year:kind==='소득'?year:null,status:'검토 중',at:now()});certSession=null;persist();render();toast('시연 확인 요청을 기록했어요.');return true;}
return false;}
setInterval(()=>{if(active==='features'&&view==='credentials')updateCertCountdown();},1000);


async function action(raw){const [a,...rest]=raw.split(':'),v=rest.join(':'),n=Number(v),c=context;
if(a==='home-hearts'){show('heartbox');return;}
if(curationAction(a,n))return;
if(a==='story-edit'){show('story');return;}if(a==='story-discovery'){show('discovery');return;}
const pages=['story-match','wallet','convert','ledger','rewards','extra','prefs','blocks','contact-block','visibility','settings','account','nickname','invite','inquiry','terms-info','logout-confirm','reset-confirm','credentials','community','compose-post','exchange','activity','notifications','places','coupons','point-ledger','point-help','place-help','hidden','community-guide','permission-help','withdraw','withdraw-assets','real-name','terms-list','terms-service','terms-privacy','profile-review'];
if(['map-search','map-locate','map-retry','map-reset','map-select','map-widen','place-expand','shop-map','shop-address','coupon-detail','coupon-tab','exchange-tab','exchange-release-do','unhide-one','notification-permission','withdraw-do','cert-code','cert-submit','gray-toggle','notice-open','my-preview','community-topic','compose-prompt'].includes(a)){await auditAction(a,v,n,c);return;}
if(pages.includes(a)){if(a==='community')tab='새 글';navTo(a);return;}
if(a==='pack'){navTo('pack',{amount:n});return;}
if(a==='charge'){R.ledger(state,n,'시연 충전',now());toast(n+'리프를 시연 잔액에 더했어요.');navTo('wallet');}
else if(a==='points-all'){$('fx-points').value=state.points;$('fx-convert-preview').textContent=Math.floor(state.points/150)+'리프';return;}
else if(a==='convert-submit'){if(!R.convert(state,Number($('fx-points').value),now())){toast('보유 포인트 안에서 150P 이상 입력해주세요.');return;}navTo('ledger');}
else if(a==='prefs-save'){const min=Number($('fx-min').value),max=Number($('fx-max').value);if(!$('fx-age-any').checked&&(min<19||max>100||min>max)){toast('나이는 19~100세, 최소 나이 이하가 되지 않게 선택해주세요.');return;}state.prefs={min,max,ageAny:$('fx-age-any').checked,...Object.fromEntries(['distance','religion','smoke','drink','politics','certification'].map(k=>[k,$('fx-'+k).value]))};toast('다음 소개부터 취향을 참고할게요.');show('mypage');}
else if(a==='extra-buy'||a==='bonus'){if(!state.visible||state.reviewStatus==='pending'){navTo('visibility');return;}const id=demoMatches.findIndex((m,i)=>genderEligible(i)&&!batchIds().includes(i)&&!state.extra.includes(i)&&!unavail(i)&&!state.requests.some(r=>r.person===i&&['done','released'].includes(r.status)));if(id<0){toast('지금은 추가로 소개할 인연이 없어요.');return;}if(a==='bonus'){if(releaseHour<21||batchIds().length<8||!batchIds().every(i=>openedMatches.has(i))){toast('공개된 오늘의 인연 8명을 모두 확인해주세요.');return;}if(state.bonusDay===R.day(now())){toast('오늘의 보너스는 이미 받았어요.');return;}state.bonusDay=R.day(now());}else if(!spend(3,'추가 인연'))return;state.extra.push(id);matchIndex=id;show('match-profile');}
else if(['hide','block','unblock'].includes(a)){const key=a==='hide'?'hidden':'blocks';if(a==='unblock')state.blocks=state.blocks.filter(i=>i!==n);else if(!state[key].includes(n))state[key].push(n);toast(a==='hide'?'오늘의 인연에서 숨겼어요.':a==='block'?'사용자를 차단했어요.':'차단을 해제했어요.');show(a==='unblock'?'mypage':'discovery');}
else if(a==='unhide'){state.hidden=[];toast('숨긴 인연을 다시 표시해요.');show('discovery');}
else if(a==='block-confirm'||a==='report'||a==='request'){navTo(a,{person:n,post:c.id});return;}
else if(a==='report-submit'){state.reports.push({person:n,reason:$('fx-reason').value,body:$('fx-report').value,at:now(),post:c.post});toast('시연 신고를 기록했어요.');show('discovery');}
else if(a==='reopen-pay'){if(!spend(10,'프로필 다시 보기'))return;state.unlocks[n]=now()+7*R.DAY;matchIndex=n;show('match-profile');}
else if(a==='reply'){const l=state.letters.find(x=>x.id===v);navTo('compose-letter',{person:l.person,reply:v});return;}
else if(a==='letter-send'){const text=$('fx-letter-body').value.trim(),k=$('fx-kakao').value.trim(),t=$('fx-phone').value.trim();if(Array.from(text.replace(/\s/g,'')).length<5){toast('편지는 공백을 제외하고 5자 이상 적어주세요.');return;}if(!k&&!t||t&&!/^\+?[0-9 ()-]{8,20}$/.test(t)){toast('카카오톡 ID 또는 올바른 전화번호를 입력해주세요.');return;}if(c.reply){if(!R.reply(state,c.reply,text,{k,t},now())){toast('잔액이나 편지 상태를 확인해주세요.');return;}delete state.drafts[c.person];openLetter(c.reply);}else{const cost=$('fx-letter-type').value.includes('80')?80:40;if(!R.send(state,{person:c.person,cost,body:text,myContact:{k,t}},now())){toast('잔액이 부족하거나 이미 보낸 편지가 있어요.');return;}delete state.drafts[c.person];navTo('letter',{id:state.letters[0].id});}toast('시연 편지를 보냈어요.');}
else if(a==='decline'){navTo('letter-decline',{id:v});return;}
else if(a==='decline-confirm'){const l=state.letters.find(x=>x.id===v);if(l)l.declined=true;show('chats');}
else if(a==='upgrade'){const l=state.letters.find(x=>x.id===v);if(!l||l.cost!==40||l.connectedAt||['기간 만료','거절','리프 반환'].includes(R.status(l,now())))return;if(!spend(40,'초대장 전환'))return;l.cost=80;render();}
else if(a==='person'){if(view==='exchange'&&!state.requests.some(r=>r.person===n&&r.status==='done')){toast('교환이 완료된 프로필만 볼 수 있어요.');return;}const origin={view,context:{...context}};matchIndex=n;profileOrigin='discovery';show('match-profile');const b=document.querySelector('#match-profile .ob-top button');b.onclick=()=>navTo(origin.view,origin.context,false);b.setAttribute('aria-label','이전 화면으로');}
else if(a==='chat'){matchIndex=n;const l=state.letters.find(x=>x.person===n&&x.connectedAt);if(!l)return;if(!letterThreads.has(n))letterThreads.set(n,[{from:l.direction==='in'?'them':'me',text:l.body},{from:l.direction==='in'?'me':'them',text:l.reply}]);openLetterChat();}
else if(a==='community-sort'){tab=v;render();}
else if(a==='post'){navTo('post',{id:v});return;}
else if(a==='post-save'){const topic=$('fx-post-topic').value,text=$('fx-post-body').value.trim(),photoFiles=[...$('fx-post-photo').files],audio=$('fx-post-audio').files[0];if(photoFiles.length>3){toast('사진은 최대 3장이에요.');return;}if([...photoFiles,audio].filter(Boolean).some(f=>f.size>1024*1024)){toast('시연 첨부는 파일당 1MB 이하로 선택해주세요.');return;}const old=state.posts.find(p=>p.id===c.id);if(!text&&!photoFiles.length&&!audio&&!old?.photos?.length&&!old?.audio){toast('내용이나 첨부 파일을 넣어주세요.');return;}const read=f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});const photos=photoFiles.length?await Promise.all(photoFiles.map(read)):old?.photos||[],sound=audio?await read(audio):old?.audio||'';if(old){old.topic=topic;old.body=text;old.photos=photos;old.audio=sound;}else{state.posts.unshift({id:uid(),author:'me',topic,body:text,photos,audio:sound,likes:[],comments:[],at:now()});const n=R.reward(state,'post',now());if(n)toast('첫 이야기 · 1리프 적립');}communityTopic='전체';tab='새 글';navTo('community');}
else if(['post-like','edit-post','delete-post-confirm','delete-post','comment-save','comment-like','comment-delete','comment-edit','comment-reply','reply-cancel'].includes(a)){const p=state.posts.find(p=>p.id===c.id);if(!p)return;if(a==='post-like'){p.likes=p.likes.includes('me')?p.likes.filter(x=>x!=='me'):[...p.likes,'me'];render();}if(a==='edit-post'){navTo('compose-post',{id:p.id});return;}if(a==='delete-post-confirm'){navTo('delete-post-confirm',{id:p.id});return;}if(a==='delete-post'){state.posts=state.posts.filter(x=>x.id!==p.id);navTo('community');}if(a==='comment-save'){const text=$('fx-comment').value.trim();if(!text){toast('댓글을 적어주세요.');return;}if(c.editComment){const edit=p.comments.find(x=>x.id===c.editComment&&x.author==='me');if(edit)edit.body=text;delete c.editComment;}else{p.comments.push({id:uid(),author:'me',body:text,parent:c.parent,at:now()});R.reward(state,'comment',now());}delete c.parent;render();}if(a==='comment-like'){const x=p.comments.find(x=>x.id===v);x.likes=(x.likes||[]).includes('me')?x.likes.filter(i=>i!=='me'):[...(x.likes||[]),'me'];render();}if(a==='comment-edit'){const x=p.comments.find(x=>x.id===v&&x.author==='me');if(x){c.editComment=v;$('fx-comment').value=x.body;$('fx-comment').focus();}}if(a==='comment-delete'){const removeIds=new Set([v]);let changed=true;while(changed){changed=false;for(const x of p.comments)if(removeIds.has(x.parent)&&!removeIds.has(x.id)){removeIds.add(x.id);changed=true;}}p.comments=p.comments.filter(x=>!removeIds.has(x.id));render();}if(a==='comment-reply'){c.parent=v;render();$('fx-comment').focus();}if(a==='reply-cancel'){delete c.parent;render();}}
else if(a==='request-send'){if(!state.visible||state.reviewStatus==='pending'){toast('인연 프로필을 공개한 뒤 요청해주세요.');return;}if(state.requests.some(r=>r.person===n&&['received','sent','done','released'].includes(r.status))){toast('이미 요청하거나 교환한 상대예요.');return;}if(!spend(10,'프로필 교환 요청'))return;state.requests.push({id:uid(),person:n,direction:'out',status:'sent',at:now(),context:'당신의 이야기가 반가웠어요.',post:c.post});navTo('exchange');}
else if(a.startsWith('exchange-')){const r=state.requests.find(r=>r.id===v);if(!r)return;if(a==='exchange-accept'&&r.status==='received'){if(!state.visible||state.reviewStatus==='pending'){toast('프로필이 공개·승인된 뒤 수락할 수 있어요.');return;}r.status='done';state.hidden.push(r.person);exchangeTab='교환 기록';}if(a==='exchange-decline'&&r.status==='received'){r.status='declined';exchangeTab='교환 기록';}if(a==='exchange-release'&&r.status==='done'){navTo('exchange-release-confirm',{id:v});return;}render();}
else if(a==='place-filter'){placeTab=v;selectedShop=null;updatePlaceResults();}
else if(a==='shop'){navTo('shop',{id:n});return;}
else if(a==='coupon-get'){if(!state.coupons.some(x=>x.store===n))state.coupons.push({store:n,at:now(),used:false});navTo('coupon-detail',{id:n});}
else if(a==='coupon-confirm'){navTo('coupon-confirm',{id:n});return;}
else if(a==='coupon-use'){const coupon=state.coupons.find(x=>x.store===n);if(coupon&&!coupon.used&&now()-coupon.at<7*R.DAY){coupon.used=true;coupon.usedAt=now();}couponTab='사용 완료';navTo('coupons');}
else if(a==='visibility-toggle'){state.visible=!state.visible;show('mypage');}
else if(a==='nickname-save'){const nick=$('fx-nickname').value.trim();if(!nick||Array.from(nick).length>6||nick===$('nickname').value){toast('현재와 다른 1~6글자 이름을 입력해주세요.');return;}if(state.nickChanges&&!spend(80,'닉네임 변경'))return;state.nickChanges++;$('nickname').value=nick;show('mypage');}
else if(a==='copy-link'){try{await navigator.clipboard.writeText('https://yahwa-first-frame-review.bluehour011.chatgpt.site/');toast('체험 링크를 복사했어요.');}catch{toast('주소창의 링크를 복사해주세요.');}}
else if(a==='inquiry-save'){const text=$('fx-inquiry').value.trim();if(text.length<5){toast('5자 이상 입력해주세요.');return;}state.inquiries.unshift({id:uid(),at:now(),body:text});render();toast('시연 문의를 기록했어요.');}
else if(a==='logout'){show('welcome');}
else if(a==='reset'){localStorage.removeItem(KEY);location.reload();return;}

persist();syncNotificationBadges();}
