const topics=[['산책',['산책','걷','걸어','한강']],['책',['책','독서','서점','문장']],['카페',['카페','커피','라떼']],['전시',['전시','미술','작품']],['여행',['여행','바다','기차']],['운동',['운동','러닝','등산']],['요리',['요리','집밥','도시락','파스타']],['음악',['음악','노래','공연']],['다정한 대화',['다정','대화','이야기','존중']],['천천히 알아가기',['천천히','편안','여유','속도']]];
function extractTopics(text){return topics.filter(([,words])=>words.some(w=>String(text).split(/[.!?。\n]/).some(sentence=>sentence.includes(w)&&!/(싫|안 좋아|좋아하지|관심 없)/.test(sentence)))).map(([label])=>label);}
function ownTopics(){return extractTopics(completedQuestions().map(i=>answers[i]).join(' '));}
function sharedTopics(m){const own=ownTopics(),other=extractTopics(m.answers.map(a=>a.answer).join(' '));return own.filter(t=>other.includes(t));}
function recommendationScore(m){return state.storyMatching&&completedQuestions().length>=3?sharedTopics(m).length:0;}
const CURATION_COST=10;
const curationDay=()=>new Date(now()+9*3600000).toISOString().slice(0,10);
function curationState(){state.curation=state.curation||{opened:{},days:{}};return state.curation;}
function curationAllowed(i){const m=demoMatches[i],p=state.prefs;if(!m||!genderEligible(i)||unavail(i)||m.visible===false||m.deleted)return false;const age=Number(m.meta.match(/\d+/)?.[0]);if(!p.ageAny&&(p.min&&age<p.min||p.max&&age>p.max))return false;return [['종교','religion'],['흡연','smoke'],['음주','drink']].every(([k,v])=>!p[v]||p[v]==='상관없음'||canonicalFact(m.facts[k])===canonicalFact(p[v]));}
function curationFit(m){const shared=sharedTopics(m),tags=(m.tags||[]).filter(t=>selectedTags.has(t));const own=completedQuestions().map(i=>answers[i]).join(' '),other=m.answers.map(a=>a.answer).join(' ');const traits=[['천천히 알아가는 만남',['천천히','속도']],['서로를 존중하는 대화',['존중','배려']],['편안한 일상',['편안','소소','평범']]];const matched=traits.filter(([,words])=>words.some(w=>own.includes(w))&&words.some(w=>other.includes(w)));const mbti=Object.values(m.facts).find(v=>/^[EI][NS][TF][JP]$/.test(v)),same=mbti&&mbti===$('mbti').value;return {score:shared.length*3+tags.length*2+matched.length*4+(same?0.5:0),reasons:[...matched.map(([label])=>'두 분의 소개에 '+label+'이 담겨 있어요.'),...(shared.length?['함께 좋아하는 '+shared.join(' · ')]:[]),...tags.map(t=>'같은 관심 태그 #'+t)].slice(0,2)};}
function curationCandidates(){const c=curationState();return demoMatches.map((m,i)=>({m,i,...curationFit(m)})).filter(x=>curationAllowed(x.i)&&!openedMatches.has(x.i)&&!state.extra.includes(x.i)&&!c.opened[x.i]&&!sentInterests.has(x.i)&&!state.requests.some(r=>r.person===x.i&&['done','released'].includes(r.status))&&x.reasons.length).sort((a,b)=>(state.prefs.certification==='인증 인연 우선'?Number(hasApprovedCert(b.m))-Number(hasApprovedCert(a.m)):0)||b.score-a.score).slice(0,3);}
function storyMatchView(){const c=curationState(),today=c.days[curationDay()]||[],items=curationCandidates(),valid=completedQuestions().length>=3;return `<div class="curation-header"><h1>당신을 위한 인연</h1><p>당신의 자기소개와 취향을 고려해 추천해요.</p></div><div class="curation-summary"><span>오늘 열어본 인연 <b>${today.length} / 3</b></span><button data-fx="wallet">${state.balance} 리프 ›</button></div>`+(!state.visible||state.reviewStatus==='pending'?'<div class="fx-card"><p>프로필 공개와 확인이 끝나면 이용할 수 있어요.</p>'+button('내 공개 상태','visibility')+'</div>':!valid?'<div class="fx-card"><p>20자 이상 이야기를 3개 작성해주세요.</p>'+button('내 이야기 채우기','story-edit')+'</div>':today.length>=3?'<div class="fx-card"><h2>오늘의 세 인연을 모두 만났어요</h2><p>새로운 큐레이션은 내일 다시 확인해주세요.</p></div>':items.length?'<div class="curation-list" tabindex="0" aria-label="추천 인연 카드, 좌우로 넘기기">'+items.slice(0,3-today.length).map((x,n)=>`<article class="curation-card"><div class="curation-photo"><img src="${esc(x.m.photos[0].src)}" alt="아직 열지 않은 추천 인연"></div><div class="curation-card-arrows"><button data-fx="curation-prev" aria-label="이전 추천 카드" ${n===0?'disabled':''}>‹</button><button data-fx="curation-next" aria-label="다음 추천 카드" ${n===Math.min(items.length,3-today.length)-1?'disabled':''}>›</button></div><small>FOR YOU · ${String(n+1).padStart(2,'0')}</small><h2>당신을 위한 추천</h2><ul>${x.reasons.map(t=>{const prefix=t.startsWith('함께 좋아하는 ')?'함께 좋아하는 ':t.startsWith('같은 관심 태그 ')?'같은 관심 태그 ':'';return '<li>'+(prefix?'<span class="curation-reason-label">'+esc(prefix.trim())+'</span><strong>'+esc(t.slice(prefix.length))+'</strong>':esc(t))+'</li>';}).join('')}</ul>${button('10리프 사용 · 열기','curation-confirm:'+x.i)}</article>`).join('')+'</div>':'<div class="fx-card"><h2>새로운 인연을 찾고 있어요</h2><p>오늘의 소개와 겹치지 않는 후보가 아직 없어요. 리프는 차감되지 않아요.</p>'+button('추천 취향 확인','prefs','fx-small')+'</div>')+`<p class="curation-swipe-hint">옆으로 넘겨 다음 인연을 만나보세요</p><p class="curation-price">한 명당 10리프 · 다시 보기는 무료</p><details class="curation-explain"><summary>어떻게 추천하나요?</summary><p>자기소개 주제·관계 성향·해시태그를 비교해요. MBTI는 보조 정보이며 궁합 점수가 아니에요.</p><p>현재는 브라우저에서 규칙으로 비교하는 UI 시연이에요. 외부 AI와 실제 결제는 연결되지 않았어요. 상대방의 필수 조건·정확한 거리 등 없는 데이터는 판단하지 않아요.</p><p>한국 시간 자정에 3명 한도가 초기화돼요. 이미 연 카드는 재차감하지 않아요.</p></details>`+(Object.keys(c.opened).length?'<h2>열어본 인연</h2><div class="curation-history">'+Object.keys(c.opened).map(Number).filter(curationAllowed).map(i=>`<button data-fx="curation-view:${i}"><img src="${esc(demoMatches[i].photos[0].src)}" alt=""><span>${esc(demoMatches[i].name)}</span><span>다시 보기 ›</span></button>`).join('')+'</div>':'');}
function curationAction(a,n){if(!a.startsWith('curation-'))return false;if(a==='curation-prev'||a==='curation-next'){const list=body.querySelector('.curation-list');if(list)list.scrollBy({left:(a==='curation-next'?1:-1)*(list.clientWidth+12),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return true;}const c=curationState();if(a==='curation-view'){if(!c.opened[n]||!curationAllowed(n))return true;action('person:'+n);return true;}if(!state.visible||state.reviewStatus==='pending'||completedQuestions().length<3){toast('프로필 공개 상태와 이야기를 확인해주세요.');return true;}if(c.opened[n]){action('curation-view:'+n);return true;}const day=curationDay(),opened=c.days[day]||[];if(opened.length>=3){toast('오늘은 3명을 모두 열었어요.');navTo('story-match');return true;}const candidate=curationCandidates().find(x=>x.i===n);if(!candidate){toast('추천 후보가 변경됐어요. 다시 확인해주세요.');navTo('story-match');return true;}if(a==='curation-confirm'){body.innerHTML='<div class="curation-header"><h1>이 인연을 만나볼까요?</h1><p>카드를 열면 10리프가 사용돼요.</p></div><div class="fx-card"><p>보유 '+state.balance+'리프'+(state.balance>=10?' → 열람 후 '+(state.balance-10)+'리프':'')+'</p><p>오늘 남은 열람 '+(3-opened.length)+'명</p></div>'+(state.balance<10?'<p>리프가 '+(10-state.balance)+'개 부족해요.</p>'+button('리프 충전','wallet'):button('10리프 사용하고 열기','curation-buy:'+n))+button('취소','story-match','fx-small');return true;}if(a==='curation-buy'){if(state.balance<10){toast('리프가 부족해요.');navTo('wallet');return true;}const previous=JSON.parse(JSON.stringify(state));if(!R.ledger(state,-10,'맞춤 인연 열람',now()))return true;c.opened[n]={at:now(),reasons:candidate.reasons};c.days[day]=[...opened,n];try{localStorage.setItem(KEY,JSON.stringify(state));}catch{state=previous;toast('저장하지 못해 리프를 차감하지 않았어요.');return true;}openedMatches.add(n);syncNotificationBadges();persist();navTo('story-match',{},false);action('person:'+n);return true;}return true;}

