 const sentences=answer.match(/[^.!?。]+[.!?。]?/g)||[answer];
 const options=sentences.map(v=>v.trim()).filter(Boolean);let scene=options.find(v=>v.length>=20&&v.length<=60)||'';if(!scene){for(const sentence of options){scene+=(scene?' ':'')+sentence;if(scene.length>=20)break;}}if(scene.length<20){scene=(m.answers||[]).map(a=>(a.answer||'').trim()).find(v=>v.length>=20)||((m.story||'').trim().length>=20?m.story:'');}
 if(!scene)return;
