const connectedDraw=drawRelease;drawRelease=function(){const schedule=$('waiting-tab');schedule?.remove();connectedDraw();const tools=$('fx-home-tools');if(tools){tools.innerHTML='<div class="home-recommendations"><button class="home-condition" data-fx="prefs"><span class="menu-symbol" aria-hidden="true">☷</span><span><b>취향 설정</b><small>만나고 싶은 인연의 조건</small></span><span aria-hidden="true">›</span></button><button class="home-ai" data-fx="story-match"><span class="menu-symbol" aria-hidden="true">✧</span><span><b>맞춤 인연 추천</b><small>내 이야기와 취향으로 찾는 인연</small></span><span aria-hidden="true">›</span></button></div>';}let total=$('home-daily-count');if(!total){total=document.createElement('span');total.id='home-daily-count';$('daily-tab').after(total);}total.textContent=($('release-label').textContent.match(/\d+\s*\/\s*8/)||[''])[0];const extra=tools?.querySelector('.home-extra-row');if(extra)dailyGrid.append(extra);let wallet=$('home-wallet');if(!wallet){wallet=document.createElement('button');wallet.id='home-wallet';wallet.dataset.fx='wallet';document.querySelector('#discovery .home-head').insertBefore(wallet,document.querySelector('#discovery .home-heart-link'));}wallet.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19C1 7 12 3 21 3c0 11-6 18-14 14M4 21 16 9"/></svg><span>'+esc(state.balance)+' 리프</span>';connectedDecorations();syncNotificationBadges();};
