const connectedSettings=settingsView;settingsView=function(){return connectedSettings()+'<h2>프로필 공개 설정</h2><label class="fx-row"><span>최근 활동 표시<br><small>끄면 내 활동과 상대의 활동 표시를 함께 숨겨요.</small></span><input aria-label="최근 활동 표시" id="activity-toggle" class="fx-switch" type="checkbox" '+(state.settings.activity?'checked':'')+'></label><small>최근 24시간 이내 여부만 표시해요. 현재 활동 정보는 가상 예시예요.</small>';};
