const outingDay=new Date();outingDay.setHours(0,0,0,0);
const outings=[];let outingFeed=null,outingFeedError=false,outingLimit=20;
function outingIcon(kind){const paths={paper:'M8 5h15v22H8z M12 11h7 M12 16h7 M12 21h4',sun:'M5 23h24 M10 20a8 8 0 0 1 16 0 M18 4v4 M5 10l3 3 M28 10l-3 3',music:'M13 22V8l13-3v14 M13 10l13-3 M13 22c0 5-8 5-8 1s8-4 8-1 M26 19c0 5-8 5-8 1s8-4 8-1',frame:'M4 5h26v23H4z M8 23l7-9 6 7 4-5 5 7 M10 10h1'};return '<svg viewBox="0 0 34 34" aria-hidden="true"><path d="'+paths[kind]+'"/></svg>';}
const outingDates=e=>new Date(e.start).toLocaleDateString('ko-KR',{month:'numeric',day:'numeric'})+' – '+new Date(e.end).toLocaleDateString('ko-KR',{month:'numeric',day:'numeric'});
function filteredOutings(){let from=outingDay.getTime(),until=from+86400000-1;if(curateDate==='이번 주'){from-=((outingDay.getDay()+6)%7)*86400000;until=from+7*86400000-1;}if(curateDate==='이번 주말'){from+=(outingDay.getDay()===0?-1:6-outingDay.getDay())*86400000;until=from+2*86400000-1;}return outings.filter(e=>(curateMode!=='saved'||state.savedOutings.includes(e.id))&&(curateCategory==='전체'||e.category===curateCategory)&&(curateRegion==='전체'||e.address.startsWith(curateRegion))&&(curateDate==='전체'||e.start<=until&&e.end>=from)&&(!curateQuery||(e.title+e.area+e.address+e.venue+(e.description||'')+(e.tags||[]).join(' ')).includes(curateQuery)));}
function outingPhoto(e){return e.imageUrl?`<img class="outing-photo poster" src="${esc(e.imageUrl)}" alt="${esc(e.title)} 대표 이미지" loading="lazy" onerror="this.remove()">`:'';}
function outingCard(e){const saved=state.savedOutings.includes(e.id);return `<article class="outing-card"><button class="outing-open" data-cur="detail:${e.id}"><div class="outing-art art-${e.art}">${outingIcon(e.art)}${outingPhoto(e)}<span>${e.category}</span></div><div class="outing-copy"><small>${esc(e.area)} · ${outingDates(e)}</small><h3>${esc(e.title)}</h3><p>${esc(e.priceText||'요금 확인 필요')}</p></div></button><button class="outing-save" data-cur="save:${e.id}" aria-label="${esc(e.title)} ${saved?'저장 취소':'저장'}" aria-pressed="${saved}">${saved?'♥':'♡'}</button></article>`;}
function placeMainNav(){return `<nav class="place-main-nav" aria-label="플레이스 주요 메뉴"><button data-cur="mode:discover" aria-pressed="${curateMode!=='stores'}"><span>전시·놀거리</span><small>새로운 장면 발견</small></button><button data-cur="mode:stores" aria-pressed="${curateMode==='stores'}"><span>카페·맛집 혜택</span><small>주변 매장 · 쿠폰</small></button></nav>`;}
function categoryDrawing(v){const paths={'전체':'M5 5h9v9H5z M20 5h9v9h-9z M5 20h9v9H5z M20 20h9v9h-9z','전시':'M5 6l24-1v24L5 28z M9 23l7-9 6 7 3-4 M11 11h1','팝업':'M5 13h24v16H5z M3 13l4-8h20l4 8 M3 13q4 6 8 0q6 6 11 0q5 6 9 0 M14 29v-9h7v9','축제':'M4 7q13 9 26 0 M6 9l3 9 6-6 M19 12l6 6 3-9 M12 25l2-3 M24 26l-1-3','공연·콘서트':'M13 24V9l14-4v16 M13 12l14-4 M13 24c0 5-8 5-8 1s8-4 8-1 M27 21c0 5-8 5-8 1s8-4 8-1'};return '<svg viewBox="0 0 34 34" aria-hidden="true"><path d="'+paths[v]+'"/></svg>';}
const originalPlacesView=placesView;
placesView=function(){if(curateMode==='stores')return placeMainNav()+originalPlacesView();const items=filteredOutings();return `${placeMainNav()}<div class="cur-heading"><h1>이번 주, 어디 갈까?</h1><p>팝업부터 전시까지, 함께 가고 싶은 곳</p></div><nav class="cur-modes" aria-label="플레이스 보기">${[['discover','발견'],['map','지도'],['saved','저장 '+state.savedOutings.length]].map(([v,l])=>`<button data-cur="mode:${v}" aria-pressed="${curateMode===v}">${l}</button>`).join('')}</nav><form id="cur-search" class="cur-search"><input aria-label="행사나 동네 검색" placeholder="행사나 동네를 찾아보세요" value="${esc(curateQuery)}"><button type="submit">검색</button></form><div class="cur-filters"><button data-cur="region">${curateRegion==='전체'?'전국':curateRegion} ⌄</button>${['전체','오늘','이번 주','이번 주말'].map(v=>`<button data-cur="date:${v}" aria-pressed="${curateDate===v}">${v==='전체'?'모든 날짜':v}</button>`).join('')}</div><div class="cur-categories">${['팝업','전시','축제','공연·콘서트','전체'].map(v=>`<button data-cur="category:${v}" aria-pressed="${curateCategory===v}"><span class="cur-category-icon">${categoryDrawing(v)}</span><span>${v}</span></button>`).join('')}</div>${curateMode==='map'?'<div id="cur-map" aria-label="행사 위치 지도"></div><p id="cur-map-note" role="status"></p>':''}<div class="cur-list-title"><h2>${curateMode==='saved'?'다음에 가고 싶은 곳':curateDate==='이번 주말'?'주말의 작은 계획':'발견한 장면'}</h2><span>${items.length}곳</span></div><div class="outing-grid">${items.length?items.slice(0,outingLimit).map(outingCard).join(''):'<div class="cur-empty">'+(curateMode==='saved'?'아직 이 조건에 저장한 곳이 없어요.':'이 조건에 맞는 행사가 아직 없어요. 다른 지역이나 날짜로 찾아보세요.')+'<button data-cur="reset">전체 둘러보기</button></div>'}</div>${items.length>outingLimit?'<button class="cur-more" data-cur="more">더 보기 · '+(items.length-outingLimit)+'곳</button>':''}<p class="cur-sample-note">${outingFeed?'행사별 출처 확인 · '+new Date(outingFeed.generatedAt).toLocaleDateString('ko-KR')+' 갱신':outingFeedError?'행사를 불러오지 못했어요. 잠시 후 새로고침해주세요.':'공식 행사 정보를 불러오고 있어요.'}<br>변경·취소 여부는 방문 전 공식 안내를 확인해주세요.</p>`;};
function outingDetail(e){if(!e)return '<p>행사 정보를 찾을 수 없어요.</p>';const saved=state.savedOutings.includes(e.id);const link=u=>/^https?:\/\//.test(u||'')?esc(u):'';return `<div class="outing-detail-art art-${e.art}">${outingIcon(e.art)}${outingPhoto(e)}</div><small>${esc(e.category)} · ${esc(e.area)}</small><h1 class="cur-detail-title">${esc(e.title)}</h1>${e.description?'<p class="cur-description">'+esc(e.description)+'</p>':''}<dl class="fx-shop-details">${[['일정',outingDates(e)],['시간',e.hours],['장소',e.venue],['지역',e.address],['요금',e.priceText],['대상',e.audience],['문의',e.inquiry],['주최·운영',e.organizer]].map(([k,v])=>v?'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>':'').join('')}</dl><a class="primary cur-official" href="${link(e.bookingUrl||e.sourceUrl)}" target="_blank" rel="noopener noreferrer">행사 안내·예약 확인 ↗</a><button class="cur-more" data-cur="save:${e.id}">${saved?'저장했어요':'가고 싶은 곳으로 저장'}</button><div class="fx-actions">${Number.isFinite(e.lat)&&Number.isFinite(e.lng)?'<button class="fx-small" data-cur="locate:'+e.id+'">지도에서 보기</button>':''}<button class="fx-small" data-cur="copy:${e.id}">정보 복사</button></div><p class="cur-sample-note"><a href="${link(e.sourceUrl)}" target="_blank" rel="noopener noreferrer">출처: ${esc(e.sourceName||'행사 안내')}</a>${e.imageLicense?'<br>'+esc(e.imageLicense):e.imageCredit?'<br>'+esc(e.imageCredit):''}<br>일정과 요금은 주최 측 사정에 따라 변경될 수 있어요.</p>`;}
const curRender=render;render=function(){curRender();if(view==='outing-detail'){page.dataset.view='outing-detail';body.innerHTML=outingDetail(outings.find(e=>e.id===context.id));}if(view==='places'&&curateMode==='map'){const host=$('cur-map'),items=filteredOutings().filter(e=>Number.isFinite(e.lat)&&Number.isFinite(e.lng));if(!window.L){$('cur-map-note').textContent='지도 연결이 어려워요. 아래 목록을 이용해주세요.';return;}curateMap=L.map(host,{zoomControl:false,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false}).setView([36.3,127.8],6);L.control.zoom({position:'topright'}).addTo(curateMap);const layer=L.tileLayer('https://{s}.tile.openstreetmap.fr/hot/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap · HOT · OSM France'}).addTo(curateMap);layer.on('tileerror',()=>{if($('cur-map-note'))$('cur-map-note').textContent='지도를 일부 불러오지 못했어요. 아래 목록은 이용할 수 있어요.';});const pins=L.layerGroup().addTo(curateMap);const paint=()=>{pins.clearLayers();const groups=new Map();items.forEach(e=>{const pt=curateMap.project([e.lat,e.lng],curateMap.getZoom()),key=Math.floor(pt.x/52)+':'+Math.floor(pt.y/52);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e);});groups.forEach(group=>{const lat=group.reduce((n,e)=>n+e.lat,0)/group.length,lng=group.reduce((n,e)=>n+e.lng,0)/group.length;const marker=L.marker([lat,lng],{title:group.length>1?group.length+'개 행사':group[0].title,icon:L.divIcon({className:'cur-map-pin',html:'<span>'+group.length+'</span>',iconSize:[36,36],iconAnchor:[18,18]})}).addTo(pins);marker.getElement().onclick=event=>{event.preventDefault();event.stopPropagation();selectSheet('이 위치의 행사',group.length+'개의 행사를 확인해보세요.',group.map(e=>[e.title,e.id,false]),id=>{closeChoice();navTo('outing-detail',{id});});choiceLayer.querySelector('.choice-options').style.gridTemplateColumns='1fr';};});};curateMap.on('zoomend',paint);paint();$('cur-map-note').textContent=items.length?'숫자를 누르면 해당 위치의 행사를 볼 수 있어요.':'이 지역에 표시할 행사 위치가 아직 없어요.';if(context.outing){const e=outings.find(e=>e.id===context.outing);if(e&&Number.isFinite(e.lat)&&Number.isFinite(e.lng))curateMap.setView([e.lat,e.lng],15);}else if(items.length)curateMap.fitBounds(items.map(e=>[e.lat,e.lng]),{padding:[24,24],maxZoom:14});}};
const curDispose=disposeMap;disposeMap=function(){if(curateMap){curateMap.stop();curateMap.remove();curateMap=null;}curDispose();};
const curNav=syncAppNav;syncAppNav=function(name){curNav(name);if(name==='features'&&view==='outing-detail'){page.querySelectorAll('.home-nav button').forEach(b=>b.removeAttribute('aria-current'));page.querySelector('[data-feature-tab="places"]')?.setAttribute('aria-current','page');}};
body.addEventListener('submit',e=>{if(e.target.id!=='cur-search')return;e.preventDefault();curateQuery=e.target.querySelector('input').value.trim();render();});
body.addEventListener('click',async event=>{const b=event.target.closest('[data-cur]');if(!b)return;const [a,v]=b.dataset.cur.split(':');if(a==='more'){outingLimit+=20;const y=body.scrollTop;render();body.scrollTop=y;}if(['mode','date','category','reset'].includes(a))outingLimit=20;if(a==='mode'){curateMode=v;context={};render();body.scrollTop=0;}if(a==='date'){curateDate=v;render();}if(a==='category'){curateCategory=v;render();}if(a==='region')selectSheet('어디로 떠날까요?','지역을 선택해주세요. 확인된 행사부터 보여드려요.', ['전체','서울','경기','인천','부산','대구','광주','대전','울산','세종','강원','충북','충남','전북','전남','경북','경남','제주'].map(v=>[v==='전체'?'전국':v,v,curateRegion===v]),v=>{curateRegion=v;context={};outingLimit=20;closeChoice();render();});if(a==='detail')navTo('outing-detail',{id:v});if(a==='save'){const at=state.savedOutings.indexOf(v);if(at<0)state.savedOutings.push(v);else state.savedOutings.splice(at,1);persist();const scroll=body.scrollTop;render();body.scrollTop=scroll;toast(at<0?'가고 싶은 곳에 저장했어요.':'저장을 취소했어요.');}if(a==='locate'){curateMode='map';curateCategory='전체';curateDate='전체';curateRegion='전체';curateQuery='';navTo('places',{outing:v});}if(a==='reset'){curateMode='discover';curateCategory='전체';curateDate='오늘';curateRegion='전체';curateQuery='';render();}if(a==='copy'){const e=outings.find(e=>e.id===v);try{await navigator.clipboard.writeText(e.title+' / '+e.venue+' / '+outingDates(e)+' / '+e.sourceUrl);toast('행사 정보를 복사했어요.');}catch{toast('복사를 지원하지 않는 환경이에요.');}}});

fetch('data/outings.json?v=91',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('feed');return r.json();}).then(feed=>{if(!Array.isArray(feed.events))throw Error('feed');outingFeed=feed;outings.splice(0,outings.length,...feed.events.filter(e=>e.end>=Date.now()));if(active==='features'&&view==='places')render();}).catch(()=>{outingFeedError=true;if(active==='features'&&view==='places')render();});

