completedQuestions=function(){return [...chosen].filter(validAnswer).sort((a,b)=>a===0?-1:b===0?1:0);};
const novRemove=removeQuestion;removeQuestion=function(id){if(Number(id)===0){toast('간단한 자기소개는 공통 필수 질문이에요.');return;}novRemove(id);};
renderQuestions=function(){chosen.add(0);novQuestionRender();const next=$('story-next');if(next)next.disabled=!validAnswer(0)||completedQuestions().length<3;const root=$('story');let note=$('common-question-note');if(!note){note=document.createElement('p');note.id='common-question-note';note.className='common-question-note';root.querySelector('.ob-intro')?.after(note);}note.remove();const intro=root.querySelector('.ob-intro');if(intro)intro.textContent='간단한 자기소개와 선택 질문 2개 이상을 작성해주세요.';const status=root.querySelector('.q-status');if(status){const count=completedQuestions().filter(id=>id!==0).length;status.textContent='필수 소개 '+(validAnswer(0)?'완료':'미작성')+' · 선택 답변 '+count+'개 완료';status.style.color=validAnswer(0)&&count>=2?'#6887A0':'#B3434E';}root.querySelectorAll('.q-option').forEach(b=>{if(b.querySelector('span')?.textContent===questions[0])b.querySelector('small').textContent='필수'+(validAnswer(0)?' · 완료':'');});};
const novCount=questionCount;questionCount=function(){novCount();if($('story-next'))$('story-next').disabled=!validAnswer(0)||completedQuestions().length<3;};
