const factArt={키:'M7 3h10v18H7ZM7 7h4M7 11h6M7 15h4', '나의 성격':'M4 5h16v12H9l-5 4ZM8 9h8M8 13h5', '학력':'m2 8 10-5 10 5-10 5ZM6 11v6q6 5 12 0v-6', '종교':'M12 3v18M6 9h12', '흡연':'M3 13h18v5H3ZM16 13v5M7 3q-3 3 0 5M12 3q-3 3 0 5', '음주':'M7 3h10v5a5 5 0 0 1-10 0ZM12 13v8M8 21h8'};
