const novRender=render;render=function(){novRender();if(view==='my-contact'){body.innerHTML=title('내 연락처','서로 답장을 나눈 인연에게만 공개돼요.')+'<label>연락처<input id="nov-contact" inputmode="tel" autocomplete="tel" value="'+esc(state.myContact||'')+'" placeholder="01012345678"></label><button class="primary" id="nov-contact-save">저장하기</button><p class="fx-note">시연용 정보예요. 실제 전송은 하지 않아요.</p>';$('nov-contact-save').onclick=()=>{const value=$('nov-contact').value.replace(/[^0-9]/g,'');if(!/^01[016789][0-9]{7,8}$/.test(value)){toast('휴대전화 번호를 확인해주세요.');return;}state.myContact=value;persist();toast('연락처를 저장했어요.');};}if(view==='compose-post'){const t=$('fx-post-topic');if(t){t.closest('label')?.setAttribute('hidden','');t.parentElement.querySelector('.fx-choice-trigger')?.setAttribute('hidden','');}}if(view==='places'){body.querySelector('.place-main-nav')?.remove();}if(view==='account'){body.insertAdjacentHTML('beforeend',myGroup('인연 관리',myItem('인연 공개 설정','visibility','cloud')+myItem('프로필 확인 상태','profile-review','note')+myItem('내 활동 · 프로필 교환','activity','note')));}if(view==='credentials'){const label=$('fx-cert-value')?.closest('label');if(label)label.firstChild.textContent='학교·회사명 또는 휴대전화 번호';}};

const poRender=render;render=function(){poRender();if(view==='settings'){body.querySelectorAll('[data-setting]').forEach(el=>{const key=el.dataset.setting;if(state.settings[key]===undefined){state.settings[key]=state.settings.app!==false;el.checked=state.settings[key];}});}if(view==='account')body.innerHTML=title('계정 관리')+row('닉네임 변경','nickname')+row(state.visible?'인연 쉬어가기':'인연 다시 시작하기','visibility')+row('로그아웃','logout-confirm')+row('회원 탈퇴','withdraw');if(view==='wallet')body.innerHTML=title('리프 충전')+'<p class="po-price">보유 '+state.balance+' 리프</p>'+[[8900,90],[16900,200],[34900,500],[69900,1300],[139000,3000]].map(([price,n])=>row(n.toLocaleString()+' 리프','pack:'+n,price.toLocaleString()+'원')).join('')+'<p class="fx-note">시연용 충전이며 실제 결제되지 않아요.</p>';if(view==='extra')body.innerHTML=title('새로운 인연을 만나볼까요?')+'<div class="extra-summary"><span>추가 소개</span><strong>2명</strong><span>사용 리프</span><strong>3 리프</strong></div><div class="extra-actions">'+button('3리프로 소개받기','po-extra-buy')+button('다음에 할게요','po-extra-cancel','fx-small')+'</div>';if(view==='my-settings')body.innerHTML=title('설정 · 도움말')+row('계정 관리','account')+row('차단 관리','blocks')+row('알림 설정','settings')+row('문의하기','inquiry')+row('약관 · 개인정보 안내','terms-list');if(view==='saved-contacts')body.innerHTML=title('내 연락처','서로 답장을 나눈 인연에게 공개할 연락처예요.')+row('카카오톡 ID','po-contact:kakao',state.savedContact?.kakao||'등록하기')+row('휴대전화 번호','po-contact:phone',state.savedContact?.phone||'등록하기');if(view==='po-contact'){const key=context.key;body.innerHTML=title(key==='phone'?'휴대전화 번호':'카카오톡 ID')+'<label class="po-contact-label">'+(key==='phone'?'휴대전화 번호':'카카오톡 ID')+'<input id="po-contact-value" maxlength="40" value="'+esc(state.savedContact?.[key]||'')+'" placeholder="'+(key==='phone'?'01012345678':'카카오톡 ID를 입력해주세요')+'"></label>'+button('저장하기','po-contact-save');}if(view==='profile-edit'){body.innerHTML=visualProfileEdit();}};
document.addEventListener('click',e=>{const raw=e.target.closest('[data-fx]')?.dataset.fx;if(!raw)return;const [a,v]=raw.split(':');if(!['my-settings','saved-contacts','profile-edit','po-contact','po-contact-save','po-extra-buy','po-extra-cancel','po-profile'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();if(['my-settings','saved-contacts','profile-edit'].includes(a))navTo(a);else if(a==='po-contact')navTo('po-contact',{key:v});else if(a==='po-profile')show(v);else if(a==='po-extra-cancel')show('discovery');else if(a==='po-contact-save'){const key=context.key,value=$('po-contact-value').value.trim();if(!value||(key==='phone'&&!/^01[016789][0-9]{7,8}$/.test(value.replace(/-/g,'')))){toast('연락처를 확인해주세요.');return;}state.savedContact={...state.savedContact,[key]:value};persist();navTo('saved-contacts');}else if(a==='po-extra-buy'){if(!state.visible||state.reviewStatus==='pending'){navTo('visibility');return;}const ids=demoMatches.map((m,i)=>i).filter(i=>genderEligible(i)&&!batchIds().includes(i)&&!state.extra.includes(i)&&!unavail(i)&&!state.requests.some(r=>r.person===i&&['done','released'].includes(r.status))).slice(0,2);if(ids.length<2){toast('새로운 두 사람을 준비하고 있어요. 리프는 차감되지 않아요.');return;}if(!spend(3,'추가 소개 2명'))return;state.extra.push(...ids);persist();show('discovery');drawRelease();toast('새로운 두 사람을 소개했어요.');}},true);
const poCommunity=communityView;communityView=function(){let html=poCommunity();const host=document.createElement('div');host.innerHTML=html;host.querySelectorAll('.comm-tools,.exchange-arrival,.comm-question,.comm-privacy,.comm-feed-heading,.comm-sort').forEach(e=>e.remove());const sort=document.createElement('div');sort.className='po-community-tabs';sort.innerHTML=['전체','공감순','내 글'].map(t=>'<button data-fx="community-sort:'+t+'" aria-pressed="'+(tab===t||t==='전체'&&!['공감순','내 글'].includes(tab))+'">'+t+'</button>').join('')+'<button data-fx="community-guide">이용수칙</button>';host.querySelector('.comm-heading').after(sort);if(tab==='내 글')host.querySelectorAll('.comm-entry').forEach(el=>{const id=el.querySelector('[data-fx]').dataset.fx.split(':')[1];if(state.posts.find(p=>p.id===id)?.author!=='me')el.remove();});if(tab==='공감순'){const feed=host.querySelector('.comm-feed');[...feed.children].sort((a,b)=>{const likes=el=>state.posts.find(p=>'post:'+p.id===el.querySelector('[data-fx]')?.dataset.fx)?.likes.length||0;return likes(b)-likes(a);}).forEach(el=>feed.append(el));}host.insertAdjacentHTML('beforeend','<button class="po-compose" data-fx="compose-post">＋ 글쓰기</button>');return host.innerHTML;};
