function poSyncPhotos(){document.querySelectorAll('#photos .photo-slot').forEach((slot,i)=>{slot.querySelectorAll('img,.po-photo-menu,.po-cover').forEach(e=>e.remove());slot.querySelector('span').hidden=!!photoUrls[i];if(!photoUrls[i])return;const img=document.createElement('img');img.src=photoUrls[i];img.alt=i?'등록 사진 '+(i+1):'대표 사진';slot.append(img);if(i===0)slot.insertAdjacentHTML('beforeend','<small class="po-cover">대표</small>');const b=document.createElement('button');b.type='button';b.className='po-photo-menu';b.textContent='···';b.setAttribute('aria-label','사진 '+(i+1)+' 관리');b.onclick=e=>{e.preventDefault();e.stopPropagation();poPhotoMenu(i);};slot.append(b);});syncNavProfilePhoto();}
function poPhotoMenu(i){const d=document.createElement('dialog');d.className='po-photo-dialog';d.innerHTML='<h2>사진 관리</h2>';[['대표 사진으로',()=>{photoUrls.unshift(photoUrls.splice(i,1)[0]);},i===0],['앞으로 이동',()=>{[photoUrls[i-1],photoUrls[i]]=[photoUrls[i],photoUrls[i-1]];},i===0],['뒤로 이동',()=>{[photoUrls[i+1],photoUrls[i]]=[photoUrls[i],photoUrls[i+1]];},!photoUrls[i+1]],['사진 삭제',()=>{photoUrls.splice(i,1);photoUrls.push(null);},false]].forEach(([label,action,disabled])=>{const b=document.createElement('button');b.textContent=label;b.disabled=disabled;b.onclick=()=>{action();poSyncPhotos();persist();d.close();d.remove();};d.append(b);});const close=document.createElement('button');close.textContent='닫기';close.onclick=()=>{d.close();d.remove();};d.append(close);d.oncancel=()=>d.remove();$('photos').append(d);d.showModal();}
document.querySelectorAll('input[data-photo]').forEach(input=>input.onchange=async()=>{const file=input.files[0];if(!file)return;poPhotoBusy=true;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024)throw Error('12MB 이하 JPG, PNG, WebP 사진을 선택해주세요.');const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('사진을 읽을 수 없어요. 다른 사진을 선택해주세요.'));im.src=src;});const scale=Math.min(1,1100/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);photoUrls[Number(input.dataset.photo)]=c.toDataURL('image/jpeg',.85);poSyncPhotos();persist();$('photo-error').textContent='';}catch(e){$('photo-error').textContent=e.message||'사진을 다시 선택해주세요.';}finally{poPhotoBusy=false;input.value='';}});
