document.addEventListener('click',e=>{const menu=document.getElementById('fx-home-tools');if(menu?.classList.contains('nov-menu-open')&&(!e.target.closest('#nov-filter'))){if(!e.target.closest('#fx-home-tools')||e.target.closest('[data-fx]')){menu.classList.remove('nov-menu-open');document.getElementById('nov-filter')?.setAttribute('aria-expanded','false');}}});
